-- Hernán pasa a atender «seco», pero se corrige solo la fila del cliente 6
update atiende set servicio = 'seco' where operador = 'Hernán' and cliente_id = 6;
select operador, count(distinct servicio) as servicios from atiende group by operador having count(distinct servicio) > 1;

create table operadores (operador text primary key, servicio text not null);
create table asignaciones (
  cliente_id int  not null,
  operador   text not null references operadores (operador),
  primary key (cliente_id, operador)
);
