create table clientes  (cliente_id int primary key, nombre text not null, rubro text not null);
create table depositos (deposito_id int primary key, nombre text not null, zona text not null);
create table bultos (
  bulto_id    int primary key,
  fecha       date not null,
  cliente_id  int not null references clientes (cliente_id),
  deposito_id int not null references depositos (deposito_id),
  estado      text not null,
  peso_kg     numeric(6,2) not null
);
select setseed(0.42);
insert into clientes
select g, 'Cliente ' || lpad(g::text, 4, '0') || ' ' || (array['SA','SRL','y Hnos.','SAS'])[1 + g % 4],
       (array['ferretería','librería','farmacia','electro','vivero','panadería','repuestos','juguetería'])[1 + g % 8]
from generate_series(1, 2000) g;
insert into depositos
select g, 'Depósito ' || lpad(g::text, 2, '0'), (array['Norte','Sur','Oeste','Centro'])[1 + g % 4]
from generate_series(1, 20) g;
insert into bultos
select g, date '2026-01-01' + (random()*300)::int, 1 + (random()*1999)::int, 1 + (random()*19)::int,
       (array['entregado','entregado','entregado','en_camino','devuelto'])[1 + (random()*4)::int],
       round((0.5 + random()*30)::numeric, 2)
from generate_series(1, 1000000) g;
create index bultos_cliente_fecha on bultos (cliente_id, fecha);

-- la misma información en una sola tabla ancha
create table bultos_ancha as
select b.bulto_id, b.fecha, b.cliente_id, c.nombre as cliente_nombre, c.rubro as cliente_rubro,
       b.deposito_id, d.nombre as deposito_nombre, d.zona as deposito_zona, b.estado, b.peso_kg
from bultos b join clientes c using (cliente_id) join depositos d using (deposito_id);
alter table bultos_ancha add primary key (bulto_id);
create index ancha_cliente_fecha on bultos_ancha (cliente_id, fecha);

-- y una tabla de resumen, calculada una vez
create table resumen as
select d.zona, c.rubro, date_trunc('month', b.fecha)::date as mes, count(*) as bultos, round(sum(b.peso_kg)) as kilos
from bultos b join clientes c using (cliente_id) join depositos d using (deposito_id)
where b.estado = 'entregado' group by 1,2,3;

