-- ¿el resumen coincide con recalcular? (después de cargar solo con inserciones)
select count(*) as preguntas_distintas from salud_calculada c join salud_preguntas p using (pregunta)
where c.respuestas is distinct from p.respuestas or c.acierto is distinct from p.acierto or c.segundos is distinct from p.segundos;

-- alguien corrige 10 aciertos a mano en la pregunta q-0042
update respuestas set acierto = not acierto where pregunta = 'q-0042' and id in (select id from respuestas where pregunta = 'q-0042' limit 10);
select 'resumen' as origen, acierto from salud_preguntas where pregunta = 'q-0042'
union all select 'recalculado', acierto from salud_calculada where pregunta = 'q-0042';
